{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2"],
  "evidencias": [
    {
      "documento": "T1",
      "seccion": "S1",
      "fragmento": "La presencia de un cerrojo violeta activo impide autorizar la transferencia de cualquier cápsula, incluso cuando el registro de transferencia esté validado."
    }
  ],
  "justificacion_breve": "El texto oficial indica que el cerrojo violeta activo bloquea la autorización de la transferencia, contradiciendo la afirmación de que la validación del registro permite autorizar el traslado mientras el cerrojo está activo."
}

{
  "decision": "CONTRADICHA",
  "reglas": ["D1", "D2"],
  "evidencias": [
    {
      "documento": "T2",
      "seccion": "S1",
      "fragmento": "La regla general permite admitir un recipiente cuando su lectura de entrada se encuentra entre 14 y 18 grados Celsius, incluidos ambos extremos."
    },
    {
      "documento": "T2",
      "seccion": "S1",
      "fragmento": "Existe una excepción a la regla de temperatura: no se admite ningún recipiente cuyo sello presente una fisura visible, aunque su lectura de entrada pertenezca al intervalo permitido."
    }
  ],
  "justificacion_breve": "Aunque la temperatura de 16 °C está dentro del rango permitido, el documento especifica explícitamente que recipientes con sello fisurado visible están excluidos, contradiciendo la afirmación."
}

{
  "decision": "RESPALDADA",
  "reglas": ["D1"],
  "evidencias": [
    {
      "documento": "T3",
      "seccion": "S1",
      "fragmento": "El procedimiento Brumel compara la lectura de dos alícuotas de una solución indicadora inerte... El criterio analítico ordinario exige dos lecturas concordantes, una de cada alícuota."
    },
    {
      "documento": "T3",
      "seccion": "S1",
      "fragmento": "Además de la concordancia analítica, la validación requiere una ficha de calibración vigente del instrumento que cubra el intervalo completo entre la primera y la segunda lectura."
    },
    {
      "documento": "T3",
      "seccion": "S1",
      "fragmento": "La decisión de validar debe registrarse antes del cierre del lote."
    }
  ],
  "justificacion_breve": "El texto del Manual Brumel (T3, S1) establece los tres requisitos citados: dos lecturas concordantes, ficha de calibración vigente que cubra ambas lecturas y registro de la decisión antes del cierre del lote, coincidiendo exactamente con la afirmación."
}
